<?php
namespace App\Http\Controllers\Booking;

use App\Http\Controllers\Controller;
use App\Services\BookingSlots;
use App\Support\XlsxExport;
use Illuminate\Http\Request;
use Illuminate\Support\Carbon;
use Illuminate\Support\Facades\DB;

class ExportController extends Controller
{
    public function export(Request $r,string $type)
    {
        $types=['bookings','payments','refunds','settlements','counselor-earnings','reception-performance','room-utilization','capacity'];abort_unless(in_array($type,$types,true),404);
        $financial=in_array($type,['payments','refunds','settlements','counselor-earnings'],true);
        abort_unless($r->user()->hasAdminPermission($financial?'finance.view':'appointments.manage'),403);
        $v=$r->validate(['from'=>'required|date_format:Y-m-d','to'=>'required|date_format:Y-m-d|after_or_equal:from',
            'counselor_id'=>'nullable|integer|exists:counselors,id','service_id'=>'nullable|integer|exists:booking_services,id',
            'status'=>'nullable|in:held,confirmed,checked_in,in_progress,completed,cancelled,expired,no_show,created,pending,verified,failed,refunded,requested,approved,rejected,processing']);
        $from=Carbon::parse($v['from'],BookingSlots::TIMEZONE)->startOfDay()->utc();$to=Carbon::parse($v['to'],BookingSlots::TIMEZONE)->addDay()->startOfDay()->utc();
        abort_if($from->diffInDays($to)>367,422,'Export range may not exceed 366 days.');
        $bookings=fn()=>DB::table('bookings as b')->join('users as u','u.id','=','b.user_id')->join('counselors as c','c.id','=','b.counselor_id')->join('booking_services as s','s.id','=','b.booking_service_id')
            ->where('b.starts_at','>=',$from)->where('b.starts_at','<',$to)->when($v['counselor_id']??null,fn($q,$id)=>$q->where('b.counselor_id',$id))
            ->when($v['service_id']??null,fn($q,$id)=>$q->where('b.booking_service_id',$id))->when($v['status']??null,fn($q,$s)=>$q->where('b.status',$s));
        $headers=[];$rows=null;
        if($type==='bookings'){$headers=['شناسه رزرو','تاریخ محلی','مراجع','مشاور','خدمت','وضعیت','حالت جلسه','مبلغ کل (ریال)','تخفیف (ریال)','پرداخت‌شده (ریال)','مدت (دقیقه)'];$query=$bookings()->select('b.id','b.starts_at','u.name as client','c.name as counselor','s.title as service','b.status','b.session_mode','b.total_irr','b.discount_irr','b.paid_irr','b.duration_minutes')->orderBy('b.id');$rows=(function()use($query){foreach($query->cursor() as $x)yield [$x->id,Carbon::parse($x->starts_at,'UTC')->setTimezone(BookingSlots::TIMEZONE)->format('Y-m-d H:i'),$x->client,$x->counselor,$x->service,$x->status,$x->session_mode,(int)$x->total_irr,(int)$x->discount_irr,(int)$x->paid_irr,(int)$x->duration_minutes];})();}
        elseif($type==='payments'){$headers=['شناسه','رزرو','درگاه','وضعیت','مبلغ (ریال)','مرجع','زمان پرداخت UTC'];$query=DB::table('booking_payments as p')->join('bookings as b','b.id','=','p.booking_id')->where('p.created_at','>=',$from)->where('p.created_at','<',$to)->when($v['counselor_id']??null,fn($q,$id)=>$q->where('b.counselor_id',$id))->when($v['service_id']??null,fn($q,$id)=>$q->where('b.booking_service_id',$id))->when($v['status']??null,fn($q,$s)=>$q->where('p.status',$s))->select('p.id','p.booking_id','p.provider','p.status','p.amount_irr','p.provider_reference','p.verified_at')->orderBy('p.id');$rows=$query->cursor()->map(fn($x)=>[$x->id,$x->booking_id,$x->provider,$x->status,(int)$x->amount_irr,$x->provider_reference,$x->verified_at]);}
        elseif($type==='refunds'){$headers=['شناسه استرداد','رزرو','مراجع','وضعیت','مبلغ مبنا (ریال)','مبلغ استرداد (ریال)','درخواست در UTC','مرجع انتقال'];$query=DB::table('booking_refunds as f')->join('bookings as b','b.id','=','f.booking_id')->join('users as u','u.id','=','b.user_id')->where('f.created_at','>=',$from)->where('f.created_at','<',$to)->when($v['counselor_id']??null,fn($q,$id)=>$q->where('b.counselor_id',$id))->when($v['service_id']??null,fn($q,$id)=>$q->where('b.booking_service_id',$id))->when($v['status']??null,fn($q,$s)=>$q->where('f.status',$s))->select('f.id','f.booking_id','u.name','f.status','f.base_amount_irr','f.refund_amount_irr','f.created_at','f.transfer_reference')->orderBy('f.id');$rows=$query->cursor()->map(fn($x)=>[$x->id,$x->booking_id,$x->name,$x->status,(int)$x->base_amount_irr,(int)$x->refund_amount_irr,$x->created_at,$x->transfer_reference]);}
        elseif($type==='settlements'){$headers=['شناسه تسویه','مشاور','مبلغ (ریال)','مرجع','ثبت شده در UTC','یادداشت'];$query=DB::table('booking_settlements as s')->join('counselors as c','c.id','=','s.counselor_id')->where('s.created_at','>=',$from)->where('s.created_at','<',$to)->when($v['counselor_id']??null,fn($q,$id)=>$q->where('s.counselor_id',$id))->when($v['service_id']??null,fn($q,$id)=>$q->whereExists(fn($sub)=>$sub->selectRaw('1')->from('counselor_booking_services as cbs')->whereColumn('cbs.counselor_id','s.counselor_id')->where('cbs.booking_service_id',$id)))->select('s.id','c.name','s.amount_irr','s.reference','s.created_at','s.note')->orderBy('s.id');$rows=$query->cursor()->map(fn($x)=>[$x->id,$x->name,(int)$x->amount_irr,$x->reference,$x->created_at,$x->note]);}
        elseif($type==='counselor-earnings'){$headers=['مشاور','درآمد بازه (ریال)','برگشت کمیسیون بازه (ریال)','تسویه بازه (ریال)','مانده قابل پرداخت تا پایان بازه (ریال)'];$ledger=DB::table('booking_ledger_entries as l')->join('bookings as b','b.id','=','l.booking_id')->where('l.account','counselor_payable')->whereBetween('l.created_at',[$from,$to])->when($v['service_id']??null,fn($q,$id)=>$q->where('b.booking_service_id',$id))->groupBy('b.counselor_id')->select('b.counselor_id')->selectRaw("SUM(CASE WHEN l.direction='credit' THEN l.amount_irr ELSE 0 END) earned,SUM(CASE WHEN l.direction='debit' THEN l.amount_irr ELSE 0 END) reversed");$periodPaid=DB::table('booking_settlements')->whereBetween('created_at',[$from,$to])->groupBy('counselor_id')->select('counselor_id')->selectRaw('SUM(amount_irr) settled');$balanceLedger=DB::table('booking_ledger_entries as l')->join('bookings as b','b.id','=','l.booking_id')->where('l.account','counselor_payable')->where('l.created_at','<',$to)->when($v['service_id']??null,fn($q,$id)=>$q->where('b.booking_service_id',$id))->groupBy('b.counselor_id')->select('b.counselor_id')->selectRaw("SUM(CASE WHEN l.direction='credit' THEN l.amount_irr ELSE 0 END) earned,SUM(CASE WHEN l.direction='debit' THEN l.amount_irr ELSE 0 END) reversed");$balancePaid=DB::table('booking_settlements')->where('created_at','<',$to)->groupBy('counselor_id')->select('counselor_id')->selectRaw('SUM(amount_irr) settled');$query=DB::table('counselors as c')->leftJoinSub($ledger,'l','l.counselor_id','=','c.id')->leftJoinSub($periodPaid,'p','p.counselor_id','=','c.id')->leftJoinSub($balanceLedger,'bl','bl.counselor_id','=','c.id')->leftJoinSub($balancePaid,'bp','bp.counselor_id','=','c.id')->when($v['counselor_id']??null,fn($q,$id)=>$q->where('c.id',$id))->select('c.name')->selectRaw('COALESCE(l.earned,0) earned,COALESCE(l.reversed,0) reversed,COALESCE(p.settled,0) settled,CASE WHEN COALESCE(bl.earned,0)-COALESCE(bl.reversed,0)-COALESCE(bp.settled,0)>0 THEN COALESCE(bl.earned,0)-COALESCE(bl.reversed,0)-COALESCE(bp.settled,0) ELSE 0 END payable')->orderBy('c.name');$rows=$query->cursor()->map(fn($x)=>[$x->name,(int)$x->earned,(int)$x->reversed,(int)$x->settled,(int)$x->payable]);}
        elseif($type==='reception-performance'){$headers=['کارمند','رزروهای ثبت‌شده','تکمیل‌شده','لغوشده'];$ids=DB::table('users')->where('is_admin',true)->pluck('id')->all();foreach(DB::table('users')->whereNotNull('admin_permissions')->get(['id','admin_permissions']) as $staff)if(in_array('appointments.manage',json_decode($staff->admin_permissions?:'[]',true)?:[],true))$ids[]=$staff->id;$ids=array_merge($ids,DB::table('admin_user_roles as ur')->join('admin_role_permissions as rp','rp.role_id','=','ur.role_id')->where('rp.permission','appointments.manage')->pluck('ur.user_id')->all());$query=DB::table('bookings as b')->leftJoin('users as u','u.id','=','b.created_by')->whereIn('b.created_by',array_unique($ids))->where('b.starts_at','>=',$from)->where('b.starts_at','<',$to)->when($v['counselor_id']??null,fn($q,$id)=>$q->where('b.counselor_id',$id))->when($v['service_id']??null,fn($q,$id)=>$q->where('b.booking_service_id',$id))->select('u.name')->selectRaw('COUNT(*) created_count')->selectRaw("SUM(CASE WHEN b.status='completed' THEN 1 ELSE 0 END) completed_count")->selectRaw("SUM(CASE WHEN b.status='cancelled' THEN 1 ELSE 0 END) cancelled_count")->groupBy('u.name')->orderBy('u.name');$rows=$query->cursor()->map(fn($x)=>[$x->name,(int)$x->created_count,(int)$x->completed_count,(int)$x->cancelled_count]);}
        elseif($type==='room-utilization'){$headers=['اتاق','رزروهای فعال/تکمیل‌شده','دقایق رزرو شده','دقایق قابل استفاده','درصد استفاده','ظرفیت نفر'];$query=DB::table('appointment_rooms as r')->leftJoin('bookings as b',function($j)use($from,$to,$v){$j->on('b.room_id','=','r.id')->where('b.starts_at','>=',$from)->where('b.starts_at','<',$to)->whereIn('b.status',['confirmed','checked_in','in_progress','completed'])->when($v['status']??null,fn($q,$s)=>$q->where('b.status',$s))->when($v['counselor_id']??null,fn($q,$id)=>$q->where('b.counselor_id',$id))->when($v['service_id']??null,fn($q,$id)=>$q->where('b.booking_service_id',$id));})->where('r.is_active',true)->select('r.id','r.name','r.capacity')->selectRaw('COUNT(b.id) appointments')->selectRaw('COALESCE(SUM(b.duration_minutes),0) booked_minutes')->groupBy('r.id','r.name','r.capacity')->orderBy('r.name');$rows=(function()use($query,$v){foreach($query->cursor() as $x){$available=$this->roomCapacityMinutes((int)$x->id,$v['from'],$v['to']);$booked=(int)$x->booked_minutes;yield [$x->name,(int)$x->appointments,$booked,$available,$available?round($booked*100/$available,2):0,(int)$x->capacity];}})();}
        else {abort_unless($r->user()->hasAdminPermission('appointments.manage'),403);$result=app(AdminOperationsController::class)->operationalReport($r)->getData(true)['data'];$headers=['شاخص','مقدار','واحد'];$rows=(function()use($result){yield ['ظرفیت واقعی مشاور',$result['counselor_capacity_minutes'],'دقیقه'];yield ['ظرفیت محدودشده با اتاق',$result['room_constrained_capacity_minutes'],'دقیقه'];yield ['زمان استفاده شده',$result['utilized_minutes'],'دقیقه'];foreach($result['counselors'] as $c)yield [$c['counselor_name'].' / ظرفیت',$c['scheduled_minutes'],'دقیقه'];})();}
        return XlsxExport::download('consulting-'.$type.'-'.$v['from'].'-'.$v['to'].'.xlsx',$headers,$rows);
    }

    private function roomCapacityMinutes(int $room,string $from,string $to):int
    {
        $first=Carbon::parse($from,BookingSlots::TIMEZONE)->startOfDay();$last=Carbon::parse($to,BookingSlots::TIMEZONE)->startOfDay();
        $roomHours=DB::table('appointment_room_working_hours')->where('room_id',$room)->get()->groupBy('weekday');
        $centerHours=DB::table('center_operating_hours')->get()->keyBy('weekday');
        $holidays=DB::table('center_holidays')->whereBetween('holiday_date',[$first->toDateString(),$last->toDateString()])->get()->keyBy('holiday_date');
        $fromUtc=$first->copy()->utc();$untilUtc=$last->copy()->addDay()->utc();
        $closures=DB::table('appointment_room_unavailability')->where('room_id',$room)->where('starts_at','<',$untilUtc)->where('ends_at','>',$fromUtc)->get()
            ->map(fn($w)=>[Carbon::parse($w->starts_at,'UTC')->setTimezone(BookingSlots::TIMEZONE),Carbon::parse($w->ends_at,'UTC')->setTimezone(BookingSlots::TIMEZONE)]);
        $minutes=0;
        for($day=$first->copy();$day->lte($last);$day->addDay()){
            $holiday=$holidays->get($day->toDateString());$center=$holiday??$centerHours->get($day->dayOfWeek);if($center&&!$center->is_open)continue;
            $baseStart=$center&&$center->opens_at?Carbon::parse($day->toDateString().' '.$center->opens_at,BookingSlots::TIMEZONE):$day->copy()->startOfDay();
            $baseEnd=$center&&$center->closes_at?Carbon::parse($day->toDateString().' '.$center->closes_at,BookingSlots::TIMEZONE):$day->copy()->addDay();
            $windows=$roomHours->get($day->dayOfWeek,collect());$intervals=[];
            if($windows->isEmpty())$intervals[]=[$baseStart,$baseEnd];else foreach($windows as $h){$a=Carbon::parse($day->toDateString().' '.$h->opens_at,BookingSlots::TIMEZONE);$b=Carbon::parse($day->toDateString().' '.$h->closes_at,BookingSlots::TIMEZONE);if($a->lt($baseStart))$a=$baseStart->copy();if($b->gt($baseEnd))$b=$baseEnd->copy();if($a->lt($b))$intervals[]=[$a,$b];}
            foreach($intervals as [$a,$b]){$startTs=$a->getTimestamp();$endTs=$b->getTimestamp();$blocks=[];foreach($closures as [$ca,$cb]){$lo=max($startTs,$ca->getTimestamp());$hi=min($endTs,$cb->getTimestamp());if($lo<$hi)$blocks[]=[$lo,$hi];}usort($blocks,fn($x,$y)=>$x[0]<=>$y[0]);$blocked=0;$cursor=$startTs;foreach($blocks as [$lo,$hi]){if($hi<=$cursor)continue;$blocked+=max(0,$hi-max($lo,$cursor));$cursor=max($cursor,$hi);}$minutes+=(int)floor(max(0,$endTs-$startTs-$blocked)/60);}
        }
        return $minutes;
    }
}
